from taf.fdsw.rc.interfaces.FDSW23C.fdsw import FDSW23C
from taf.fdsw.rc.interfaces.FDSW23D.swm import SoftwareManagement23D


class FDSW23D(FDSW23C):
    VERSION_NAME = 'FDSW23D'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW23D, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)

        self.swm = SoftwareManagement23D(client=self._client)
